// ╔══════════════════════════════════════════════════════════════╗
// ║  APPLY CONFIG - DO NOT EDIT THIS FILE                       ║
// ║  This script reads site-config.js and updates the website.  ║
// ╚══════════════════════════════════════════════════════════════╝

(function () {
    "use strict";

    var CONFIG = window.SITE_CONFIG;
    if (!CONFIG) {
        console.warn("SITE_CONFIG not found. Make sure site-config.js is loaded.");
        return;
    }

    // Helper: find elements containing exact text
    function findByText(tag, text) {
        var els = document.querySelectorAll(tag);
        var results = [];
        for (var i = 0; i < els.length; i++) {
            var childNodes = els[i].childNodes;
            for (var j = 0; j < childNodes.length; j++) {
                if (childNodes[j].nodeType === 3 && childNodes[j].textContent.trim() === text) {
                    results.push(els[i]);
                    break;
                }
            }
        }
        return results;
    }

    // Helper: find an element that contains text (loose match)
    function findContaining(tag, text) {
        var els = document.querySelectorAll(tag);
        var results = [];
        for (var i = 0; i < els.length; i++) {
            if (els[i].textContent.indexOf(text) !== -1) {
                results.push(els[i]);
            }
        }
        return results;
    }

    function applyConfig() {
        applyDeliveryButton();
        applyContactInfo();
        applySectionText();
        applySocialLinks();
        applyMenuItems();
        applyFullMenuImage();
        applyVendors();
        applyFooter();
        fixMobileBadge();
        removeStoryPinSpacers();
    }

    // ===== SECTION TEXT (Hero, Partners, Menu, Order) =====
    function applySectionText() {
        // --- Hero Section ---
        // Tagline (e.g. "SMASHED TO ORDER")
        if (CONFIG.heroTagline) {
            var taglines = findByText("p", "SMASHED TO ORDER");
            if (taglines.length === 0) taglines = findByText("span", "SMASHED TO ORDER");
            if (taglines.length === 0) taglines = findContaining("p", "SMASHED");
            for (var i = 0; i < taglines.length; i++) {
                taglines[i].textContent = CONFIG.heroTagline;
            }
        }

        // Subtitle (e.g. "Hot Griddle • Crispy Edges • No Shortcuts")
        if (CONFIG.heroSubtitle) {
            var subs = findContaining("p", "Hot Griddle");
            if (subs.length === 0) subs = findContaining("span", "Hot Griddle");
            for (var i = 0; i < subs.length; i++) {
                subs[i].textContent = CONFIG.heroSubtitle;
            }
        }

        // Badge (e.g. "EST. 2026")
        if (CONFIG.heroBadge) {
            var badges = findContaining("span", "EST.");
            for (var i = 0; i < badges.length; i++) {
                badges[i].textContent = CONFIG.heroBadge;
            }
        }

        // --- Stats ---
        if (CONFIG.stat1Value) {
            var s1v = findByText("span", "STFX");
            if (s1v.length === 0) s1v = findByText("span", CONFIG.stat1Value);
            for (var i = 0; i < s1v.length; i++) s1v[i].textContent = CONFIG.stat1Value;
        }
        if (CONFIG.stat1Label) {
            var s1l = findContaining("span", "GRADUATE");
            if (s1l.length === 0) s1l = findContaining("p", "GRADUATE");
            for (var i = 0; i < s1l.length; i++) s1l[i].textContent = CONFIG.stat1Label;
        }
        if (CONFIG.stat2Value) {
            var s2v = findByText("span", "4.9");
            if (s2v.length === 0) s2v = findByText("span", CONFIG.stat2Value);
            for (var i = 0; i < s2v.length; i++) s2v[i].textContent = CONFIG.stat2Value;
        }
        if (CONFIG.stat2Label) {
            var s2l = findContaining("span", "STAR RATING");
            if (s2l.length === 0) s2l = findContaining("p", "STAR RATING");
            for (var i = 0; i < s2l.length; i++) s2l[i].textContent = CONFIG.stat2Label;
        }

        // --- Partners Section ---
        var partnersSection = document.getElementById("partners");
        if (partnersSection) {
            if (CONFIG.partnersSubheading) {
                var sub = partnersSection.querySelectorAll("span, p");
                for (var i = 0; i < sub.length; i++) {
                    if (sub[i].textContent.trim() === "Local Sources" || sub[i].textContent.trim() === CONFIG.partnersSubheading) {
                        sub[i].textContent = CONFIG.partnersSubheading;
                    }
                }
            }
            if (CONFIG.partnersHeading) {
                var h2s = partnersSection.querySelectorAll("h2");
                for (var i = 0; i < h2s.length; i++) {
                    if (h2s[i].textContent.indexOf("PARTNERS") !== -1 || h2s[i].textContent.indexOf("OUR") !== -1 || h2s[i].textContent === CONFIG.partnersHeading) {
                        h2s[i].textContent = CONFIG.partnersHeading;
                    }
                }
            }
            if (CONFIG.partnersBanner) {
                var bannerEls = partnersSection.querySelectorAll("span, p, div");
                for (var i = 0; i < bannerEls.length; i++) {
                    var txt = bannerEls[i].textContent.trim();
                    if (txt.indexOf("100%") !== -1 && txt.indexOf("Local") !== -1) {
                        bannerEls[i].textContent = CONFIG.partnersBanner;
                    }
                }
            }
        }

        // --- Menu Section ---
        var menuSection = document.getElementById("menu");
        if (menuSection) {
            if (CONFIG.menuSubheading) {
                var sub = menuSection.querySelectorAll("span, p");
                for (var i = 0; i < sub.length; i++) {
                    if (sub[i].textContent.trim() === "The Menu" || sub[i].textContent.trim() === CONFIG.menuSubheading) {
                        sub[i].textContent = CONFIG.menuSubheading;
                    }
                }
            }
            if (CONFIG.menuHeading) {
                var h2s = menuSection.querySelectorAll("h2");
                for (var i = 0; i < h2s.length; i++) {
                    if (h2s[i].textContent.indexOf("Burgers") !== -1 || h2s[i].textContent === CONFIG.menuHeading) {
                        h2s[i].textContent = CONFIG.menuHeading;
                    }
                }
            }
        }

        // --- Order Section ---
        var orderSection = document.getElementById("order");
        if (orderSection) {
            if (CONFIG.orderSubheading) {
                var sub = orderSection.querySelectorAll("span, p");
                for (var i = 0; i < sub.length; i++) {
                    if (sub[i].textContent.trim() === "ORDER NOW" || sub[i].textContent.trim() === CONFIG.orderSubheading) {
                        sub[i].textContent = CONFIG.orderSubheading;
                    }
                }
            }
            if (CONFIG.orderDescription) {
                var descs = orderSection.querySelectorAll("p");
                for (var i = 0; i < descs.length; i++) {
                    if (descs[i].textContent.indexOf("fast") !== -1 || descs[i].textContent === CONFIG.orderDescription) {
                        descs[i].textContent = CONFIG.orderDescription;
                    }
                }
            }
        }
    }

    // ===== SOCIAL MEDIA LINKS (Instagram + Facebook) =====
    function applySocialLinks() {
        // Update Instagram links
        var igLinks = document.querySelectorAll('a[href*="instagram.com"]');
        for (var i = 0; i < igLinks.length; i++) {
            if (CONFIG.instagramUrl) {
                igLinks[i].href = CONFIG.instagramUrl;
            }
        }

        // Add Facebook link next to Instagram if URL is provided
        if (CONFIG.facebookUrl) {
            var igLinks = document.querySelectorAll('a[href*="instagram.com"]');
            for (var i = 0; i < igLinks.length; i++) {
                var igLink = igLinks[i];
                // Check if we already added a Facebook link
                var parent = igLink.parentElement;
                if (parent && !parent.querySelector('a[href*="facebook.com"]')) {
                    var fbLink = document.createElement("a");
                    fbLink.href = CONFIG.facebookUrl;
                    fbLink.target = "_blank";
                    fbLink.rel = "noopener noreferrer";
                    fbLink.className = igLink.className;
                    fbLink.style.cssText = igLink.style.cssText;
                    // Facebook SVG icon
                    fbLink.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z"></path></svg>';
                    // Insert after Instagram
                    if (igLink.nextSibling) {
                        parent.insertBefore(fbLink, igLink.nextSibling);
                    } else {
                        parent.appendChild(fbLink);
                    }
                }
            }
        }
    }

    // ===== REMOVE STORY PIN-SPACERS (safe version) =====
    function removeStoryPinSpacers() {
        // GSAP creates div.pin-spacer wrappers around pinned story sub-sections.
        // These have large heights even though the story content is hidden.
        // We collapse ONLY pin-spacers that don't wrap important sections.
        var pinSpacers = document.querySelectorAll(".pin-spacer");
        for (var i = 0; i < pinSpacers.length; i++) {
            var ps = pinSpacers[i];
            // NEVER collapse if it contains our important sections
            if (ps.querySelector("#partners")) continue;
            if (ps.querySelector("#menu")) continue;
            if (ps.querySelector("#order")) continue;
            if (ps.querySelector("h1")) continue;
            if (ps.querySelector(".min-h-svh")) continue;
            // This pin-spacer wraps a story sub-section — collapse it
            ps.style.cssText += ";display:none!important;height:0!important;max-height:0!important;padding:0!important;margin:0!important;overflow:hidden!important;";
        }
    }

    // ===== FIX EST BADGE ON MOBILE =====
    function fixMobileBadge() {
        if (window.innerWidth > 640) return; // Only on mobile

        // Find the EST badge by looking for elements with "EST" text
        var allEls = document.querySelectorAll("div, span");
        for (var i = 0; i < allEls.length; i++) {
            var el = allEls[i];
            var text = el.textContent.trim();
            if (text.indexOf("EST.") !== -1 && text.indexOf("2026") !== -1 && text.length < 20) {
                // Found the badge element — go up to the positioned ancestor
                var badge = el;
                // Walk up to find the absolutely positioned container
                while (badge && badge.parentElement) {
                    var style = window.getComputedStyle(badge);
                    if (style.position === "absolute") break;
                    badge = badge.parentElement;
                }
                if (badge && window.getComputedStyle(badge).position === "absolute") {
                    // Move it well above the title
                    badge.style.top = "18%";
                    badge.style.transform = "translateX(-50%) scale(0.75)";
                }
                break;
            }
        }
    }

    // ===== DELIVERY BUTTON =====
    function applyDeliveryButton() {
        // Update delivery button text
        var deliverySpans = findByText("span", "Delivery");
        for (var i = 0; i < deliverySpans.length; i++) {
            deliverySpans[i].textContent = CONFIG.deliveryName || "Nish Eats";
        }

        // Override delivery button click behavior
        var allButtons = document.querySelectorAll("button");
        for (var i = 0; i < allButtons.length; i++) {
            var btn = allButtons[i];
            var spans = btn.querySelectorAll("span");
            for (var s = 0; s < spans.length; s++) {
                if (spans[s].textContent === (CONFIG.deliveryName || "Nish Eats") || spans[s].textContent === "Delivery") {
                    spans[s].textContent = CONFIG.deliveryName || "Nish Eats";
                    (function (button) {
                        var newBtn = button.cloneNode(true);
                        button.parentNode.replaceChild(newBtn, button);
                        newBtn.addEventListener("click", function (e) {
                            e.preventDefault();
                            e.stopPropagation();
                            if (CONFIG.deliveryComingSoon || !CONFIG.deliveryLink) {
                                showComingSoonModal();
                            } else {
                                window.open(CONFIG.deliveryLink, "_blank");
                            }
                        });
                    })(btn);
                    break;
                }
            }
        }
    }

    // ===== CONTACT INFO =====
    function applyContactInfo() {
        // Phone - update ALL tel: links
        var phoneLinks = document.querySelectorAll('a[href^="tel:"]');
        for (var i = 0; i < phoneLinks.length; i++) {
            phoneLinks[i].href = "tel:" + CONFIG.phoneLink;
            phoneLinks[i].textContent = CONFIG.phone;
        }

        // Email
        var emailLinks = document.querySelectorAll('a[href^="mailto:"]');
        for (var i = 0; i < emailLinks.length; i++) {
            emailLinks[i].href = "mailto:" + CONFIG.email;
            emailLinks[i].textContent = CONFIG.email;
        }

        // Address
        var addressEls = findContaining("p", "123 Street Kitchen Ave");
        if (addressEls.length === 0) addressEls = findContaining("p", CONFIG.addressLine1);
        for (var i = 0; i < addressEls.length; i++) {
            var el = addressEls[i];
            if (el.querySelector("br")) {
                el.innerHTML = "";
                el.appendChild(document.createTextNode(CONFIG.addressLine1));
                el.appendChild(document.createElement("br"));
                el.appendChild(document.createTextNode(CONFIG.addressLine2));
            }
        }

        // Hours (supports 2 or 3 lines)
        var hoursEls = findContaining("p", "11am");
        if (hoursEls.length === 0) hoursEls = findContaining("p", CONFIG.hoursLine1);
        for (var i = 0; i < hoursEls.length; i++) {
            var el = hoursEls[i];
            el.innerHTML = "";
            el.appendChild(document.createTextNode(CONFIG.hoursLine1));
            el.appendChild(document.createElement("br"));
            el.appendChild(document.createTextNode(CONFIG.hoursLine2));
            if (CONFIG.hoursLine3) {
                el.appendChild(document.createElement("br"));
                el.appendChild(document.createTextNode(CONFIG.hoursLine3));
            }
        }
    }

    // ===== FULL MENU IMAGE =====
    function applyFullMenuImage() {
        if (!CONFIG.fullMenuImage) return;
        // Find the full menu image in the dialog
        var fullMenuImgs = document.querySelectorAll('img[alt="Full Menu"]');
        for (var i = 0; i < fullMenuImgs.length; i++) {
            fullMenuImgs[i].src = CONFIG.fullMenuImage;
        }
    }

    // ===== MENU ITEMS (Dynamic add/delete) =====
    function applyMenuItems() {
        if (!CONFIG.menuItems || CONFIG.menuItems.length === 0) return;

        var menuGrid = document.querySelector("#menu .grid");
        if (!menuGrid) return;

        var existingCards = Array.prototype.slice.call(menuGrid.children);
        var configLen = CONFIG.menuItems.length;

        // Update existing cards
        for (var i = 0; i < existingCards.length && i < configLen; i++) {
            updateMenuCard(existingCards[i], CONFIG.menuItems[i]);
        }

        // If we have MORE config items than existing cards -> create new cards
        if (configLen > existingCards.length) {
            var templateCard = existingCards[0];
            for (var i = existingCards.length; i < configLen; i++) {
                var newCard = createMenuCard(CONFIG.menuItems[i], templateCard);
                menuGrid.appendChild(newCard);
            }
        }

        // If we have FEWER config items than existing cards -> remove extras
        if (configLen < existingCards.length) {
            for (var i = existingCards.length - 1; i >= configLen; i--) {
                menuGrid.removeChild(existingCards[i]);
            }
        }

        // Force ALL menu cards to be visible
        // GSAP ScrollTrigger sets opacity:0 and transform on cards for animation.
        // Cloned cards inherit these invisible states. Reset them all.
        var allCards = menuGrid.children;
        for (var i = 0; i < allCards.length; i++) {
            allCards[i].style.opacity = "1";
            allCards[i].style.visibility = "visible";
            allCards[i].style.transform = "none";
        }
    }

    function updateMenuCard(card, item) {
        var img = card.querySelector("img");
        if (img) {
            img.src = item.image;
            img.alt = item.name;
        }

        var h3 = card.querySelector("h3");
        if (h3) h3.textContent = item.name;

        var priceSpan = card.querySelector(".font-mono.text-gold.text-lg");
        if (priceSpan) priceSpan.textContent = "$" + item.price;

        var desc = card.querySelector(".text-gray-500.text-sm");
        if (desc) desc.textContent = item.description;

        // Tags
        var tagsContainer = card.querySelector(".absolute.top-3.left-3");
        if (tagsContainer && item.tags && item.tags.length > 0) {
            tagsContainer.innerHTML = "";
            for (var t = 0; t < item.tags.length; t++) {
                var tagSpan = document.createElement("span");
                tagSpan.className = "px-2.5 py-1 bg-gold text-black text-[10px] font-mono font-bold uppercase tracking-wider rounded-full";
                tagSpan.textContent = item.tags[t];
                tagsContainer.appendChild(tagSpan);
            }
            tagsContainer.style.display = "";
        } else if (tagsContainer) {
            tagsContainer.style.display = "none";
        }
    }

    function createMenuCard(item, templateCard) {
        // Clone structure from templateCard if available, otherwise build from scratch
        if (templateCard) {
            var card = templateCard.cloneNode(true);
            updateMenuCard(card, item);
            // Reset hover state
            card.style.transform = "perspective(1000px) rotateX(0deg) rotateY(0deg)";
            return card;
        }

        // Fallback: build card from scratch
        var card = document.createElement("div");
        card.className = "group relative bg-black-charcoal rounded-xl overflow-hidden border border-white/5 will-change-transform cursor-pointer";
        card.style.transformStyle = "preserve-3d";
        card.style.transition = "transform 0.15s ease-out";

        var imgWrap = document.createElement("div");
        imgWrap.className = "relative h-48 sm:h-52 overflow-hidden";

        var img = document.createElement("img");
        img.src = item.image;
        img.alt = item.name;
        img.className = "w-full h-full object-cover transition-transform duration-500 group-hover:scale-110";
        imgWrap.appendChild(img);

        var gradient = document.createElement("div");
        gradient.className = "absolute inset-0 bg-gradient-to-t from-black-charcoal via-transparent to-transparent";
        imgWrap.appendChild(gradient);

        if (item.tags && item.tags.length > 0) {
            var tagContainer = document.createElement("div");
            tagContainer.className = "absolute top-3 left-3 flex gap-2";
            for (var t = 0; t < item.tags.length; t++) {
                var tagEl = document.createElement("span");
                tagEl.className = "px-2.5 py-1 bg-gold text-black text-[10px] font-mono font-bold uppercase tracking-wider rounded-full";
                tagEl.textContent = item.tags[t];
                tagContainer.appendChild(tagEl);
            }
            imgWrap.appendChild(tagContainer);
        }

        card.appendChild(imgWrap);

        var content = document.createElement("div");
        content.className = "p-5";

        var header = document.createElement("div");
        header.className = "flex items-start justify-between gap-3 mb-2";

        var h3 = document.createElement("h3");
        h3.className = "font-display font-bold text-lg text-white group-hover:text-gold transition-colors duration-300";
        h3.textContent = item.name;

        var price = document.createElement("span");
        price.className = "font-mono text-gold text-lg font-bold";
        price.textContent = "$" + item.price;

        header.appendChild(h3);
        header.appendChild(price);
        content.appendChild(header);

        var desc = document.createElement("p");
        desc.className = "text-gray-500 text-sm leading-relaxed line-clamp-2";
        desc.textContent = item.description;
        content.appendChild(desc);

        card.appendChild(content);
        return card;
    }

    // ===== VENDORS / PARTNERS (Complete rebuild) =====
    function applyVendors() {
        if (!CONFIG.vendors || CONFIG.vendors.length === 0) return;

        var partnersSection = document.getElementById("partners");
        if (!partnersSection) return;

        // Completely rebuild the partners section content
        // because GSAP removes/hides the original React elements

        // Preserve the top gradient line if it exists
        var gradientLine = partnersSection.querySelector(".bg-gradient-to-r");

        // Clear the section
        partnersSection.innerHTML = "";

        // Re-add gradient line
        if (gradientLine) {
            partnersSection.appendChild(gradientLine);
        } else {
            var divLine = document.createElement("div");
            divLine.className = "absolute top-0 left-0 w-full h-px bg-gradient-to-r from-transparent via-gold/30 to-transparent";
            partnersSection.appendChild(divLine);
        }

        // Main content wrapper
        var wrapper = document.createElement("div");
        wrapper.className = "relative z-10 px-6 sm:px-10 lg:px-[7vw]";

        // Header area
        var headerDiv = document.createElement("div");
        headerDiv.className = "text-center mb-12 sm:mb-16";

        // Subheading pill
        var pill = document.createElement("div");
        pill.className = "inline-flex items-center gap-2 px-4 py-2 bg-gold/10 rounded-full mb-6";
        var pillText = document.createElement("span");
        pillText.className = "font-mono text-xs text-gold uppercase tracking-[0.2em]";
        pillText.textContent = CONFIG.partnersSubheading || "Local Sources";
        pill.appendChild(pillText);
        headerDiv.appendChild(pill);

        // Main heading
        var heading = document.createElement("h2");
        heading.className = "font-display font-black text-3xl sm:text-4xl lg:text-5xl text-white uppercase leading-[0.95] mb-4";
        heading.innerHTML = (CONFIG.partnersHeading || "Local <span class='text-gradient-gold'>Sources</span>");
        headerDiv.appendChild(heading);

        // Description
        var desc = document.createElement("p");
        desc.className = "text-gray-400 text-base sm:text-lg max-w-2xl mx-auto leading-relaxed";
        desc.textContent = "We believe in supporting local. Every patty comes from Nova Scotia farms, never frozen, always fresh.";
        headerDiv.appendChild(desc);

        wrapper.appendChild(headerDiv);

        // Vendor cards grid
        var configLen = CONFIG.vendors.length;
        var grid = document.createElement("div");
        var cols = configLen <= 2 ? configLen : (configLen <= 3 ? 3 : Math.min(configLen, 4));
        grid.className = "grid gap-6 sm:gap-8";
        grid.style.gridTemplateColumns = "repeat(" + cols + ", 1fr)";

        for (var i = 0; i < configLen; i++) {
            var vendor = CONFIG.vendors[i];
            var card = document.createElement("div");
            card.className = "group relative bg-black rounded-2xl p-6 sm:p-8 border border-white/5 hover:border-gold/30 transition-all duration-300";

            // Highlight pill
            if (vendor.location) {
                var highlight = document.createElement("div");
                highlight.className = "absolute -top-3 left-6 px-3 py-1 bg-gold text-black text-[10px] font-mono font-bold uppercase tracking-wider rounded-full";
                highlight.textContent = vendor.location;
                card.appendChild(highlight);
            }


            // Name
            var nameEl = document.createElement("h3");
            nameEl.className = "font-display font-bold text-lg text-white mb-2";
            nameEl.textContent = vendor.name;
            card.appendChild(nameEl);

            // Description
            var descEl = document.createElement("p");
            descEl.className = "text-gray-500 text-sm leading-relaxed";
            descEl.textContent = vendor.description;
            card.appendChild(descEl);

            grid.appendChild(card);
        }

        wrapper.appendChild(grid);

        // Banner
        if (CONFIG.partnersBanner) {
            var bannerWrap = document.createElement("div");
            bannerWrap.className = "flex justify-center mt-12 sm:mt-16";
            var banner = document.createElement("div");
            banner.className = "inline-flex items-center gap-3 px-8 py-4 rounded-full border border-gold/20 bg-gold/5";
            var bannerIcon = document.createElement("span");
            bannerIcon.textContent = "🐂";
            bannerIcon.className = "text-xl";
            banner.appendChild(bannerIcon);
            var bannerText = document.createElement("span");
            bannerText.className = "font-mono text-sm text-gold tracking-wider";
            bannerText.textContent = CONFIG.partnersBanner;
            banner.appendChild(bannerText);
            bannerWrap.appendChild(banner);
            wrapper.appendChild(bannerWrap);
        }

        partnersSection.appendChild(wrapper);
    }

    function updateVendorCard(card, vendor) {
        var img = card.querySelector("img");
        if (img) {
            img.src = vendor.image;
            img.alt = vendor.name;
        }

        var h3 = card.querySelector("h3");
        if (h3) h3.textContent = vendor.name;

        // Update description - find the paragraph text
        var paragraphs = card.querySelectorAll("p");
        for (var i = 0; i < paragraphs.length; i++) {
            var p = paragraphs[i];
            // Skip location-style text (usually very short)
            if (p.textContent.length > 20 || p.className.indexOf("text-sm") !== -1) {
                p.textContent = vendor.description;
                break;
            }
        }

        // Update location subtitle if it exists
        var spans = card.querySelectorAll("span");
        for (var i = 0; i < spans.length; i++) {
            if (spans[i].className && spans[i].className.indexOf("text-gold") !== -1 && spans[i].className.indexOf("text-xs") !== -1) {
                spans[i].textContent = vendor.location || "";
                break;
            }
        }
    }

    function createVendorCard(vendor, templateCard) {
        if (templateCard) {
            var card = templateCard.cloneNode(true);
            updateVendorCard(card, vendor);
            return card;
        }

        // Fallback: build from scratch
        var card = document.createElement("div");
        card.className = "group relative bg-black-charcoal rounded-xl overflow-hidden border border-white/5";

        var imgWrap = document.createElement("div");
        imgWrap.className = "relative h-48 overflow-hidden";

        var img = document.createElement("img");
        img.src = vendor.image;
        img.alt = vendor.name;
        img.className = "w-full h-full object-cover";
        imgWrap.appendChild(img);

        var gradient = document.createElement("div");
        gradient.className = "absolute inset-0 bg-gradient-to-t from-black-charcoal via-transparent to-transparent";
        imgWrap.appendChild(gradient);

        card.appendChild(imgWrap);

        var content = document.createElement("div");
        content.className = "p-5";

        if (vendor.location) {
            var loc = document.createElement("span");
            loc.className = "font-mono text-xs text-gold uppercase tracking-wider mb-2 block";
            loc.textContent = vendor.location;
            content.appendChild(loc);
        }

        var h3 = document.createElement("h3");
        h3.className = "font-display font-bold text-lg text-white mb-2";
        h3.textContent = vendor.name;
        content.appendChild(h3);

        var desc = document.createElement("p");
        desc.className = "text-gray-500 text-sm leading-relaxed";
        desc.textContent = vendor.description;
        content.appendChild(desc);

        card.appendChild(content);
        return card;
    }

    // ===== FOOTER =====
    function applyFooter() {
        var footerEls = findContaining("p", "SmashBoys Kitchen. All rights reserved");
        for (var i = 0; i < footerEls.length; i++) {
            footerEls[i].textContent = CONFIG.footerText;
        }
    }

    // ===== COMING SOON MODAL =====
    function showComingSoonModal() {
        var existing = document.getElementById("coming-soon-modal-overlay");
        if (existing) existing.remove();

        var overlay = document.createElement("div");
        overlay.id = "coming-soon-modal-overlay";
        overlay.style.cssText =
            "position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);z-index:9999;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(4px);animation:csModalFadeIn 0.2s ease-out;";

        var modal = document.createElement("div");
        modal.style.cssText =
            "background:#1a1a1a;border:1px solid rgba(255,215,0,0.3);border-radius:16px;padding:40px 32px;max-width:360px;width:90%;text-align:center;box-shadow:0 0 40px rgba(255,215,0,0.1);animation:csModalScaleIn 0.3s ease-out;";

        var icon = document.createElement("div");
        icon.style.cssText =
            "width:64px;height:64px;background:rgba(255,215,0,0.1);border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 20px;font-size:28px;";
        icon.textContent = "🚀";

        var title = document.createElement("h3");
        title.style.cssText =
            "font-weight:900;font-size:22px;color:white;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:8px;";
        title.textContent = "Coming Soon!";

        var msg = document.createElement("p");
        msg.style.cssText = "color:#9ca3af;font-size:14px;line-height:1.6;margin-bottom:24px;";
        msg.textContent = (CONFIG.deliveryName || "Nish Eats") + " is launching soon. Stay tuned for online ordering!";

        var closeBtn = document.createElement("button");
        closeBtn.style.cssText =
            "padding:12px 32px;background:#ffd700;color:black;font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:0.08em;border:none;border-radius:9999px;cursor:pointer;transition:all 0.3s;";
        closeBtn.textContent = "Got It";
        closeBtn.onmouseenter = function () { closeBtn.style.boxShadow = "0 0 20px rgba(255,215,0,0.4)"; };
        closeBtn.onmouseleave = function () { closeBtn.style.boxShadow = "none"; };
        closeBtn.onclick = function () {
            overlay.style.animation = "csModalFadeOut 0.2s ease-out";
            setTimeout(function () { overlay.remove(); }, 200);
        };

        overlay.onclick = function (e) {
            if (e.target === overlay) {
                overlay.style.animation = "csModalFadeOut 0.2s ease-out";
                setTimeout(function () { overlay.remove(); }, 200);
            }
        };

        modal.appendChild(icon);
        modal.appendChild(title);
        modal.appendChild(msg);
        modal.appendChild(closeBtn);
        overlay.appendChild(modal);
        document.body.appendChild(overlay);
    }

    // Add modal animation CSS
    var style = document.createElement("style");
    style.textContent =
        "@keyframes csModalFadeIn{from{opacity:0}to{opacity:1}}" +
        "@keyframes csModalFadeOut{from{opacity:1}to{opacity:0}}" +
        "@keyframes csModalScaleIn{from{transform:scale(0.9);opacity:0}to{transform:scale(1);opacity:1}}";
    document.head.appendChild(style);

    // ===== INITIALIZATION =====
    var applied = false;

    function tryApply() {
        if (applied) return;
        var root = document.getElementById("root");
        if (root && root.children.length > 0) {
            setTimeout(function () {
                applyConfig();
                applied = true;
            }, 800);
        }
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", function () {
            setTimeout(tryApply, 1000);
        });
    } else {
        setTimeout(tryApply, 1000);
    }

    var observer = new MutationObserver(function () {
        if (!applied) tryApply();
    });
    var rootEl = document.getElementById("root");
    if (rootEl) {
        observer.observe(rootEl, { childList: true, subtree: true });
    }

    var retries = 0;
    var retryInterval = setInterval(function () {
        tryApply();
        retries++;
        if (retries > 10 || applied) {
            clearInterval(retryInterval);
            if (applied) setTimeout(applyConfig, 2000);
        }
    }, 500);

    // Persistent watcher: update ANY new tel: links that appear (e.g. Pickup modal)
    var phoneWatcher = new MutationObserver(function () {
        if (!CONFIG) return;
        var phoneLinks = document.querySelectorAll('a[href^="tel:"]');
        for (var i = 0; i < phoneLinks.length; i++) {
            if (phoneLinks[i].href !== "tel:" + CONFIG.phoneLink) {
                phoneLinks[i].href = "tel:" + CONFIG.phoneLink;
                phoneLinks[i].textContent = CONFIG.phone;
            }
        }
    });
    phoneWatcher.observe(document.body, { childList: true, subtree: true });
})();
